def main(all_files: bool = False) -> None:
    base = _git("merge-base", "HEAD", "origin/main")[0]
    changed = _git("diff", "--name-only", base) + _git("ls-files", "--others", "--exclude-standard")
    python_files = [f for f in changed if f.endswith(".py")]
    steps: list[tuple[str, list[str]]] = []
    if all_files or python_files:
        steps.append(("lint", ["pre-commit", "run", *(["--all-files"] if all_files else ["--files", *python_files])]))
    if all_files or any(f.startswith(FULL_RUN) for f in changed):
        steps.append(("cloud API tests: all", ["poe", "api-test"]))
    elif any(f.startswith(CLOUD) for f in changed):
        steps.append(("cloud API tests: affected", ["poe", "api-test-affected"]))
    if any(f.startswith("sdk/") for f in changed):
        steps.append(("sdk", ["make", "-C", "sdk", "lint", "test"]))
    failed = {name for name, cmd in steps if subprocess.run(cmd).returncode != 0}
    for name, _ in steps:
        print(f"{'FAIL' if name in failed else 'pass'}  {name}")
    if failed:
        print("Details: cloud/rhinoCloud/reports/failures.md", file=sys.stderr)
    sys.exit(1 if failed else 0)

CHECKS = [  # (what, passes, fix, safe for --fix)
    ("node " + ENGINES["node"], lambda: _at_least(_run("node", "--version"), ENGINES["node"]), "nvm install", False),
    ("Python 3.13 (uv)", lambda: _run("uv", "python", "find", "3.13"), "uv python install 3.13", True),
    ("cloud venv = uv.lock", lambda: _run("uv", "sync", "--check", "--directory", "cloud/rhinoCloud"), "make -C cloud/rhinoCloud sync-deps", True),
    ("Docker >= 16 GiB (FCP Lab)", lambda: int(_run("docker", "info", "-f", "{{.MemTotal}}") or 0) >= 16 * 2**30, "raise Docker's memory limit", False),
]


def main(fix: bool = False, as_json: bool = False) -> None:
    results = [(what, bool(passes()), how, safe) for what, passes, how, safe in CHECKS]
    for what, ok, how, safe in results:
        if fix and safe and not ok:
            subprocess.run(how, shell=True, cwd=ROOT)  # local commands only: never credentials, ~/.aws or volumes
        print(json.dumps({"check": what, "ok": ok, "fix": how}) if as_json else f"{'ok ' if ok else 'FIX'}  {what}  {'' if ok else '-> ' + how}")
    raise SystemExit(0 if all(ok for _, ok, _, _ in results) else 1)

