def pass_hat_k(successes: int, tries: int, k: int) -> float:
    """Chance that k tries picked from this task's runs all pass (tau-bench's pass^k)."""
    return comb(successes, k) / comb(tries, k) if tries >= k else float("nan")


for (kind, _), trials in by_task.items():
    wins = sum(t["reward"] == 1 for t in trials)
    by_kind[kind].append({"p1": wins / len(trials), "p3": pass_hat_k(wins, len(trials), 3),
                          "cost": mean(t["cost_usd"] for t in trials), "min": median(t["minutes"] for t in trials)})

